def _make_calculator(rate: float):
    def calc(amount: float) -> float:
        return round(amount * rate, 2)
    return calc


def build_fee_calculators(fee_rates: dict) -> dict:
    return {name: _make_calculator(rate) for name, rate in fee_rates.items()}


def compute_fees(fee_rates: dict, amount: float) -> dict:
    calculators = build_fee_calculators(fee_rates)
    return {name: calc(amount) for name, calc in calculators.items()}
